<script>
(() => {
  const onboarding = document.getElementById("wheat-onboarding-modal");
  const closeOnboarding = document.getElementById("close-wheat-onboarding");
  const openGuide = document.getElementById("open-guide-tip");
  const guideModal = document.getElementById("guide-tip-modal");
  const closeGuide = document.getElementById("close-guide-tip");
  const closeGuideTop = document.getElementById("close-guide-tip-top");
  const regionToast = document.getElementById("region-tip-toast");
  const droughtEvolve = document.getElementById("drought-option-evolve");
  const droughtIgnore = document.getElementById("drought-option-ignore");
  const droughtFeedback = document.getElementById("drought-feedback");

  const hideGuide = () => {
    if (!guideModal) return;
    guideModal.classList.add("hidden");
    guideModal.classList.remove("flex");
  };
  const showGuide = () => {
    if (!guideModal) return;
    guideModal.classList.remove("hidden");
    guideModal.classList.add("flex");
  };

  if (closeOnboarding && onboarding) {
    closeOnboarding.addEventListener("click", () => {
      onboarding.classList.add("hidden");
    });
  }

  if (openGuide) {
    openGuide.addEventListener("click", (event) => {
      event.preventDefault();
      showGuide();
    });
  }
  if (closeGuide) closeGuide.addEventListener("click", hideGuide);
  if (closeGuideTop) closeGuideTop.addEventListener("click", hideGuide);
  if (guideModal) {
    guideModal.addEventListener("click", (event) => {
      if (event.target === guideModal) hideGuide();
    });
  }

  document.querySelectorAll("[data-region-tip]").forEach((node) => {
    node.addEventListener("click", () => {
      if (!regionToast) return;
      const tip = node.getAttribute("data-region-tip") || "";
      regionToast.textContent = tip;
      regionToast.classList.remove("hidden");
      window.clearTimeout(window.__readoRegionToastTimer);
      window.__readoRegionToastTimer = window.setTimeout(() => {
        regionToast.classList.add("hidden");
      }, 2400);
    });
  });

  if (droughtEvolve && droughtFeedback) {
    droughtEvolve.addEventListener("click", (event) => {
      event.preventDefault();
      droughtFeedback.textContent = "已执行：耐旱根系进化。小麦存活率提升，DNA 点数 -15。";
      droughtFeedback.className = "mt-4 text-xs text-emerald-300 border-t border-slate-700 pt-3";
    });
  }
  if (droughtIgnore && droughtFeedback) {
    droughtIgnore.addEventListener("click", (event) => {
      event.preventDefault();
      droughtFeedback.textContent = "已执行：无视风险。传播区域衰减，后续扩张将更困难。";
      droughtFeedback.className = "mt-4 text-xs text-red-300 border-t border-slate-700 pt-3";
    });
  }
})();
</script>

