  <script>
    (() => {
      const rounds = [{"title":"回合1：建仓尺度","situation":"研究结论支持你建立对冲头寸，但团队在“分批建仓”与“重仓先手”上意见对立。","prompt":"你如何入场？","knowledgeHint":"分层建仓与风险上限能降低“对但太早”的生存压力。","optionA":{"stance":"纪律建仓","label":"分批买入保护，设定最大回撤阈值和复核节点","feedback":"收益上限被压低，但你保留了应对久期不确定性的弹性。","effects":{"stability":3,"treasury":1,"reform":2}},"optionB":{"stance":"高确信押注","label":"一次性大额建仓，争取在拐点前占满头寸","feedback":"潜在回报诱人，但短期波动足以引发被动减仓风险。","effects":{"stability":-4,"treasury":4,"reform":-1}}},{"title":"回合2：质疑风暴","situation":"市场继续上涨，你的账面表现承压，出资方要求给出“立即见效”的解释。","prompt":"你怎么沟通？","knowledgeHint":"透明披露假设边界，有助于在压力期维持决策一致性。","optionA":{"stance":"透明沟通","label":"公开模型假设、触发条件与失败情景，争取耐心资本","feedback":"你没有承诺时间点，但稳定了核心支持者的预期。","effects":{"stability":4,"treasury":-1,"reform":3}},"optionB":{"stance":"业绩叙事","label":"淡化短期风险并追加杠杆，试图尽快扳回账面","feedback":"短期可能改善曲线，但策略脆弱性被进一步放大。","effects":{"stability":-5,"treasury":3,"reform":-3}}},{"title":"回合3：对手方阴影","situation":"你担心少数大型机构若承压，合约履约与估值传导都会受影响。","prompt":"是否调整交易对手结构？","knowledgeHint":"分散对手方与追加抵押安排，可降低单点失效冲击。","optionA":{"stance":"分散与担保","label":"降低单一对手暴露，重谈抵押与结算条款","feedback":"交易成本上升，但系统性连锁风险有所缓释。","effects":{"stability":5,"treasury":-2,"reform":2}},"optionB":{"stance":"成本优先","label":"维持集中对手方以换取更低费率","feedback":"成本更好看，却把关键风险押在少数节点上。","effects":{"stability":-4,"treasury":2,"reform":-2}}}];
      const state = { i: 0, stability: 50, treasury: 50, reform: 50 };
      const titleEl = document.getElementById("round-title");
      const situationEl = document.getElementById("round-situation");
      const promptEl = document.getElementById("round-prompt");
      const hintEl = document.getElementById("round-hint");
      const reportEl = document.getElementById("report");
      const logEl = document.getElementById("event-log");
      const optA = document.getElementById("opt-a");
      const optB = document.getElementById("opt-b");
      const optAStance = document.getElementById("opt-a-stance");
      const optAEffect = document.getElementById("opt-a-effect");
      const optALabel = document.getElementById("opt-a-label");
      const optBStance = document.getElementById("opt-b-stance");
      const optBEffect = document.getElementById("opt-b-effect");
      const optBLabel = document.getElementById("opt-b-label");
      const debriefEl = document.getElementById("debrief");
      const endActionsEl = document.getElementById("end-actions");
      const retryBtn = document.getElementById("retry-btn");
      const sV = document.getElementById("s-v");
      const tV = document.getElementById("t-v");
      const rV = document.getElementById("r-v");
      const sB = document.getElementById("s-b");
      const tB = document.getElementById("t-b");
      const rB = document.getElementById("r-b");

      function clamp(v) {
        return Math.max(0, Math.min(100, Math.round(v)));
      }

      function fmtDelta(v, label) {
        const n = Number(v) || 0;
        const sign = n > 0 ? "+" : "";
        return label + " " + sign + n;
      }

      function effectSummary(effects) {
        return [
          fmtDelta(effects?.stability, "稳"),
          fmtDelta(effects?.treasury, "资"),
          fmtDelta(effects?.reform, "推")
        ].join(" · ");
      }

      function refreshBars() {
        sV.textContent = String(state.stability);
        tV.textContent = String(state.treasury);
        rV.textContent = String(state.reform);
        sB.style.width = state.stability + "%";
        tB.style.width = state.treasury + "%";
        rB.style.width = state.reform + "%";
      }

      function pushLog(text) {
        const li = document.createElement("li");
        li.textContent = text;
        logEl.prepend(li);
        while (logEl.children.length > 8) {
          logEl.removeChild(logEl.lastChild);
        }
      }

      function showFinal() {
        titleEl.textContent = "场景结算";
        situationEl.textContent = "你已完成本关全部关键抉择。";
        promptEl.textContent = "回看你的日志，检查你是否始终沿着同一因果逻辑推进。";
        hintEl.textContent = "复盘建议：提炼一条可迁移到现实的判断规则。";
        optA.style.display = "none";
        optB.style.display = "none";
        debriefEl.classList.add("show");
        endActionsEl.classList.add("show");
      }

      function paintRound() {
        const round = rounds[state.i];
        if (!round) {
          showFinal();
          return;
        }
        titleEl.textContent = round.title || ("抉择 " + (state.i + 1));
        situationEl.textContent = round.situation || "局势正在发生变化。";
        promptEl.textContent = round.prompt || "";
        hintEl.textContent = "知识锚点：" + (round.knowledgeHint || "先识别约束，再判断代价。");
        optAStance.textContent = round.optionA?.stance || "方案 A";
        optALabel.textContent = round.optionA?.label || "选项 A";
        optAEffect.textContent = "预期影响：" + effectSummary(round.optionA?.effects || {});
        optBStance.textContent = round.optionB?.stance || "方案 B";
        optBLabel.textContent = round.optionB?.label || "选项 B";
        optBEffect.textContent = "预期影响：" + effectSummary(round.optionB?.effects || {});
        optA.style.display = "";
        optB.style.display = "";
      }

      function applyChoice(option) {
        const effects = option?.effects || {};
        state.stability = clamp(state.stability + (Number(effects.stability) || 0));
        state.treasury = clamp(state.treasury + (Number(effects.treasury) || 0));
        state.reform = clamp(state.reform + (Number(effects.reform) || 0));
        refreshBars();

        const choiceLabel = option?.label || "未命名策略";
        const outcome = option?.feedback || "你完成了一次关键抉择。";
        const line = "第 " + (state.i + 1) + " 回合 · 选择「" + choiceLabel + "」 · " + effectSummary(effects);
        pushLog(line);
        reportEl.textContent = "后果速报：" + outcome;

        state.i += 1;
        window.setTimeout(() => {
          paintRound();
        }, 320);
      }

      optA.addEventListener("click", () => {
        const round = rounds[state.i];
        applyChoice(round?.optionA || {});
      });
      optB.addEventListener("click", () => {
        const round = rounds[state.i];
        applyChoice(round?.optionB || {});
      });
      if (retryBtn) {
        retryBtn.addEventListener("click", () => window.location.reload());
      }

      pushLog("已进入场景：你在衍生品会议室里谈判信用违约互换，外部市场仍在上涨，账面浮亏让质疑声越来越大。");
      pushLog("角色就位：你是一名被借调到跨机构风险小组的策略官，任务是在繁荣叙事中识别脆弱点，并给出可执行方案。");
      refreshBars();
      paintRound();

      try {
        localStorage.setItem("reado_last_experience_href", "/experiences/u-book-aae53b-02-58350f.html");
      } catch {}
    })();
  </script>
