      pushLog("角色就位：流动剧场计划总策划（兼艺术统筹）");
      refreshBars();
      paintRound();

      try {
        localStorage.setItem("reado_last_experience_href", "/experiences/u-https-eprints-whiterose--02-194bc3.html");
      } catch {}
    })();
  </script>
