            ctx.strokeStyle = `rgba(167,139,250,${(1 - d/90) * 0.2})`;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(q.x, q.y);
