        { id: "post-anime", type: "post", image: "post-anime.svg", title: "四月新番剪辑", summary: "作画崩坏与神回混剪。", tags: ["二次元", "游戏", "美食"], interestBase: -5, matchBoost: 7, hateBoost: 0 },
        { id: "post-history", type: "post", image: "post-history.svg", title: "史料里的制度细节", summary: "案例如何影响现代治理讨论。", tags: ["历史", "读书", "社会"], interestBase: -6, matchBoost: 7, hateBoost: -1 },
        { id: "post-ai", type: "post", image: "post-ai.svg", title: "多模态 Agent 实战", summary: "从 demo 到线上可用的关键差异。", tags: ["AI", "编程", "产品"], interestBase: -5, matchBoost: 8, hateBoost: 0 },
        { id: "post-career", type: "post", image: "post-career.svg", title: "会议减负模板", summary: "用异步协作减少低效例会。", tags: ["效率", "副业", "产品"], interestBase: -6, matchBoost: 7, hateBoost: 0 },
        { id: "post-parenting", type: "post", image: "post-parenting.svg", title: "儿童睡眠计划", summary: "可执行作息表与复盘手册。", tags: ["育儿", "家庭", "健康"], interestBase: -5, matchBoost: 7, hateBoost: -1 },
        { id: "post-fitness", type: "post", image: "post-fitness.svg", title: "力量+心肺周期表", summary: "12 周训练和饮食联动。", tags: ["运动", "足球", "健康"], interestBase: -5, matchBoost: 7, hateBoost: 0 },
        { id: "post-travel", type: "post", image: "post-travel.svg", title: "淡季出行攻略", summary: "预算内拿下高评分酒店。", tags: ["旅行", "时尚", "本地生活"], interestBase: -5, matchBoost: 7, hateBoost: 0 },
        { id: "post-food", type: "post", image: "post-food.svg", title: "夜宵探店地图", summary: "本地口碑店避坑清单。", tags: ["美食", "探店", "本地生活"], interestBase: -5, matchBoost: 8, hateBoost: 0 },
        { id: "post-money", type: "post", image: "post-money.svg", title: "复利与风险平衡", summary: "高收益叙事背后的资金曲线。", tags: ["理财", "副业", "效率"], interestBase: -6, matchBoost: 8, hateBoost: 0 },
        { id: "post-philosophy", type: "post", image: "post-philosophy.svg", title: "公共讨论的边界", summary: "如何避免争论滑向人身攻击。", tags: ["读书", "社会", "历史"], interestBase: -6, matchBoost: 6, hateBoost: -2 },
        { id: "hot-1", type: "hot", image: "post-controversy-1.svg", title: "震惊：你被操控了吗", summary: "情绪强刺激，极易引战。", tags: ["阴谋", "极端", "生存"], interestBase: -4, matchBoost: 10, hateBoost: 18, polarized: true },
        { id: "hot-2", type: "hot", image: "post-controversy-2.svg", title: "群体冲突升级", summary: "站队式叙事，强对立。", tags: ["极端", "突发", "生存"], interestBase: -4, matchBoost: 10, hateBoost: 20, polarized: true },
        { id: "hot-3", type: "hot", image: "post-controversy-3.svg", title: "官方不会告诉你的真相", summary: "高传播，高失真。", tags: ["阴谋", "生存", "社会"], interestBase: -4, matchBoost: 10, hateBoost: 19, polarized: true },
        { id: "hot-4", type: "hot", image: "post-controversy-4.svg", title: "必须立即站队", summary: "单向激化，抬升仇恨。", tags: ["极端", "阴谋", "突发"], interestBase: -4, matchBoost: 10, hateBoost: 21, polarized: true }
      ];

      const ADS = [
        { id: "ad-travel", type: "ad", image: "ad-travel.svg", title: "广告：机票闪促", summary: "48 小时限时折扣", tags: ["旅行", "本地生活"], cpm: 12.6, interestBase: -4, matchBoost: 6 },
        { id: "ad-snack", type: "ad", image: "ad-snack.svg", title: "广告：零食礼盒", summary: "夜宵补给 3 件 7 折", tags: ["美食", "本地生活"], cpm: 9.8, interestBase: -4, matchBoost: 6 },
        { id: "ad-cosmetic", type: "ad", image: "ad-cosmetic.svg", title: "广告：护肤新品", summary: "敏感肌也可用", tags: ["时尚", "护肤", "旅行"], cpm: 14.4, interestBase: -4, matchBoost: 7 },
        { id: "ad-finance", type: "ad", image: "ad-finance.svg", title: "广告：理财课程", summary: "从现金流到资产配置", tags: ["理财", "副业", "效率"], cpm: 16.2, interestBase: -4, matchBoost: 7 },
        { id: "ad-game", type: "ad", image: "ad-game.svg", title: "广告：新游预约", summary: "首发礼包 + 限定皮肤", tags: ["游戏", "二次元"], cpm: 11.3, interestBase: -4, matchBoost: 6 },
        { id: "ad-sports", type: "ad", image: "ad-sports.svg", title: "广告：跑鞋联名", summary: "碳板升级版", tags: ["运动", "足球", "健康"], cpm: 10.5, interestBase: -4, matchBoost: 6 },
        { id: "ad-family", type: "ad", image: "ad-family.svg", title: "广告：亲子订阅", summary: "每周成长主题包", tags: ["育儿", "家庭", "健康"], cpm: 13.1, interestBase: -4, matchBoost: 7 },
        { id: "ad-tech", type: "ad", image: "ad-tech.svg", title: "广告：云服务券", summary: "新人资源包", tags: ["AI", "编程", "产品"], cpm: 15.0, interestBase: -4, matchBoost: 7 }
      ];

      const state = {
        round: 1,
        maxRounds: MAX_ROUNDS,
        revenue: 0,
        adViews: 0,
        selectedUserId: "",
        selectedPoolId: "",
        actionResolved: false,
        gameOver: false,
        users: USERS.map((item) => ({ ...item, feed: [] })),
        activeSlots: ["u9942", "u3301", "u5520"],
        benchQueue: ["u7824", "u1170", "u8841", "u2059", "u6412", "u7390", "u9183"],
        pool: [],
        logs: []
      };

      const userBoard = document.getElementById("user-board");
      const poolGrid = document.getElementById("pool-grid");
      const selectionHint = document.getElementById("selection-hint");
      const actionResult = document.getElementById("action-result");
      const eventLog = document.getElementById("event-log");
      const metricRevenue = document.getElementById("metric-revenue");
      const metricAds = document.getElementById("metric-ads");
      const metricInterest = document.getElementById("metric-interest");
      const metricHate = document.getElementById("metric-hate");
      const metricRound = document.getElementById("metric-round");
      const roundProgress = document.getElementById("round-progress");
      const goalHint = document.getElementById("goal-hint");
      const slotHint = document.getElementById("slot-hint");
      const endTurnBtn = document.getElementById("end-turn");
      const refreshPoolBtn = document.getElementById("refresh-pool");
      const openGuideBtn = document.getElementById("open-guide");
      const restartTopBtn = document.getElementById("restart-top");
      const restartBottomBtn = document.getElementById("restart-bottom");
      const modalRoot = document.getElementById("modal-root");

      function clamp(value, min, max) {
        return Math.max(min, Math.min(max, value));
      }

      function sample(list, count) {
        const cloned = [...list];
        for (let i = cloned.length - 1; i > 0; i -= 1) {
          const j = Math.floor(Math.random() * (i + 1));
          [cloned[i], cloned[j]] = [cloned[j], cloned[i]];
        }
        return cloned.slice(0, Math.min(count, cloned.length));
      }

      function shuffle(list) {
        return sample(list, list.length);
      }

      function getUserById(id) {
        return state.users.find((item) => item.id === id) || null;
      }

      function getActiveUsers() {
        return state.activeSlots.map(getUserById).filter(Boolean);
      }

      function tagMatchScore(userTags, contentTags) {
        const userSet = new Set(userTags);
        let matches = 0;
        for (const tag of contentTags) {
          if (userSet.has(tag)) matches += 1;
        }
        return matches / Math.max(1, contentTags.length);
      }

      function randomFrom(list) {
        return list[Math.floor(Math.random() * list.length)] || "";
      }

      function pushLog(message, tone = "normal") {
        const icon = tone === "warn" ? "⚠" : (tone === "ok" ? "✓" : "•");
        state.logs.unshift(`${icon} [R${state.round}] ${message}`);
        state.logs = state.logs.slice(0, 14);
      }

      function average(values) {
        if (!values.length) return 0;
        return values.reduce((sum, value) => sum + value, 0) / values.length;
      }

      function buildPool() {
        const normalPosts = sample(POSTS.filter((item) => item.type === "post"), 4);
        const hotPosts = sample(POSTS.filter((item) => item.type === "hot"), state.round % 2 === 0 ? 2 : 1);
        const ads = sample(ADS, 3);
        const merged = shuffle([...normalPosts, ...hotPosts, ...ads]).slice(0, 8);
        state.pool = merged.map((item, index) => ({ ...item, turnId: `${item.id}-${state.round}-${index}` }));
      }

      function updateDerivedSignals(user, deliveredContent) {
        const match = tagMatchScore(user.tags, deliveredContent.tags || []);
        if (deliveredContent.type === "ad") {
          user.lastActivity = match >= 0.34 ? "正在比较广告里的商品参数" : "快速划过广告，停留很短";
        } else if (deliveredContent.type === "hot") {
          user.lastActivity = "正在反复阅读争议帖评论区";
        } else {
          user.lastActivity = match >= 0.34 ? "正在深读与你兴趣相关的内容" : "快速浏览后跳过";
        }
        user.lastSaying = randomFrom(user.saying);
        user.lastSpending = randomFrom(user.spending);
      }

      function applyPassiveDecay(targetUserId) {
        const activeUsers = getActiveUsers();
        activeUsers.forEach((user) => {
          if (user.id === targetUserId) return;
          user.interest = clamp(Math.round(user.interest - 2), 0, 100);
          user.hate = clamp(Math.round(user.hate - 1), 0, 100);
        });
      }

      function dispatchContentToUser(contentId, userId) {
        if (state.gameOver || state.actionResolved) return;
        const content = state.pool.find((item) => item.turnId === contentId);
        const user = getUserById(userId);
        if (!content || !user) return;

        const match = tagMatchScore(user.tags, content.tags || []);
        let interestDelta = content.interestBase + Math.round((content.matchBoost || 0) * match);
        let hateDelta = content.hateBoost || 0;
        let revenueGain = 0;

        if (content.type === "ad") {
          const multiplier = 0.55 + match * 0.65;
          revenueGain = Math.max(3, Math.round(content.cpm * multiplier));
          state.revenue += revenueGain;
          state.adViews += 1;
          if (match >= 0.34) {
            interestDelta += 4;
            hateDelta -= 1;
          } else {
            interestDelta -= 2;
          }
        }

        if (content.type === "hot") {
          interestDelta += 11;
          hateDelta += Math.round((1 - match) * 6);
        }

        interestDelta = clamp(Math.round(interestDelta), -20, 18);
        hateDelta = clamp(Math.round(hateDelta), -3, 28);

        user.interest = clamp(Math.round(user.interest + interestDelta), 0, 100);
        user.hate = clamp(Math.round(user.hate + hateDelta), 0, 100);

        user.feed.push({
          round: state.round,
          type: content.type,
          title: content.title,
          tags: content.tags,
          interestDelta,
          hateDelta,
          revenueGain
        });
        user.feed = user.feed.slice(-6);

        applyPassiveDecay(user.id);
        updateDerivedSignals(user, content);

        const tone = content.type === "hot" ? "warn" : "ok";
        const compact = [
          `${user.label} <- ${content.title}`,
          `兴趣 ${interestDelta >= 0 ? "+" : ""}${interestDelta}`,
          `仇恨 ${hateDelta >= 0 ? "+" : ""}${hateDelta}`,
          revenueGain ? `营收 +$${revenueGain}` : "无广告收入"
        ].join(" / ");
        pushLog(compact, tone);

        state.pool = state.pool.filter((item) => item.turnId !== content.turnId);
        state.actionResolved = true;
        state.selectedPoolId = "";

        actionResult.textContent = `${user.label} 已收到【${content.title}】。兴趣 ${interestDelta >= 0 ? "+" : ""}${interestDelta}，仇恨 ${hateDelta >= 0 ? "+" : ""}${hateDelta}${revenueGain ? `，本回合广告营收 +$${revenueGain}` : ""}。`;
        endTurnBtn.disabled = false;

        render();
        checkFailImmediately();
      }

      function rotateActiveSlotsIfNeeded() {
        if (state.round <= 1 || state.round % 3 !== 0) return;
        if (!state.benchQueue.length) return;
        const slotIndex = (Math.floor(state.round / 3) - 1) % state.activeSlots.length;
        const outgoingId = state.activeSlots[slotIndex];
        const incomingId = state.benchQueue.shift();
        if (!incomingId) return;
        state.activeSlots[slotIndex] = incomingId;
        state.benchQueue.push(outgoingId);
        if (!state.activeSlots.includes(state.selectedUserId)) {
          state.selectedUserId = state.activeSlots[0];
        }
        const incoming = getUserById(incomingId);
        pushLog(`轮换在线用户：${outgoingId.replace("u", "")} -> ${incoming ? incoming.label.replace("用户_ID: ", "") : incomingId.replace("u", "")}`);
      }

      function checkFailImmediately() {
        if (state.gameOver) return;
        const activeUsers = getActiveUsers();
        const churnUser = activeUsers.find((user) => user.interest <= 0);
        if (churnUser) {
          state.gameOver = true;
          showResultModal(false, `失败：${churnUser.label} 兴趣归零并流失。`, "你过度消耗了用户注意力，留存链路断裂。\n建议：提高相关匹配内容比例，降低连续广告和争议帖密度。");
          return;
        }
        const hateUser = activeUsers.find((user) => user.hate >= 100);
        if (hateUser) {
          state.gameOver = true;
          showResultModal(false, `失败：${hateUser.label} 仇恨值爆表。`, "算法将情绪刺激推到临界点，平台触发公共风险。\n建议：限制极化内容频率，用高相关但低对立内容回血。");
          return;
        }

        const avgHate = average(activeUsers.map((user) => user.hate));
        if (avgHate >= 75) {
          state.gameOver = true;
          showResultModal(false, "失败：三路在线用户平均仇恨超过 75%。", "你在追求短期停留时放大了群体对立，系统进入失控区。\n建议：减少争议话题，补充中性和知识型内容。\n");
        }
      }

      function evaluateFinalResult() {
        const activeUsers = getActiveUsers();
        const avgInterest = average(activeUsers.map((user) => user.interest));
        const avgHate = average(activeUsers.map((user) => user.hate));
        const success = state.revenue >= TARGET_REVENUE && avgInterest >= 40 && avgHate <= 60;

        const summary = [
          `总营收：$${state.revenue}`,
          `广告曝光：${state.adViews}`,
          `平均兴趣：${Math.round(avgInterest)}%`,
          `平均仇恨：${Math.round(avgHate)}%`,
          success ? "判定：达成商业与健康度平衡。" : "判定：目标未达成。"
        ].join("\n");

        const advice = success
          ? "你在变现与用户健康之间建立了可持续节奏。\n继续优化方向：\n1) 对广告做更细粒度场景匹配。\n2) 限制争议内容连续触达。\n3) 对低兴趣用户优先推高相关内容。"
          : "这局的问题通常来自：\n1) 广告与用户标签错配，兴趣掉太快。\n2) 争议内容过多，仇恨累积失控。\n3) 忽视了轮换用户，导致新上线路径没有冷启动策略。";

        state.gameOver = true;
        showResultModal(success, success ? "体验完成：你守住了平台平衡。" : "体验结束：平台进入高压状态。", `${summary}\n\n${advice}`);
      }

      function endTurn() {
        if (!state.actionResolved || state.gameOver) return;
        state.round += 1;
        state.actionResolved = false;
        endTurnBtn.disabled = true;

        if (state.round > state.maxRounds) {
          evaluateFinalResult();
          render();
          return;
        }

        rotateActiveSlotsIfNeeded();
        buildPool();
        if (!state.activeSlots.includes(state.selectedUserId)) {
          state.selectedUserId = state.activeSlots[0];
        }
        actionResult.textContent = "新回合开始：请继续选择目标用户与内容。";

        render();
      }

      function openGuide() {
        openModal("新手引导 / 知识提示", [
          "你扮演一家内容平台的推荐算法负责人。每回合你会从内容池选一条内容，派发到某位在线用户的瀑布流尾部。",
          "核心机制：",
          "1) 每次内容消费会自然消耗兴趣值；标签匹配会回升兴趣。",
          "2) 广告带来营收；匹配广告会降低反感，错配广告会加速流失。",
          "3) 对立/仇恨内容会短期提高兴趣，但会显著抬升仇恨值。",
          "失败条件：任一在线用户兴趣归零，或仇恨值达到 100。",
          "通关目标（28 回合）：营收 >= $320，平均兴趣 >= 40%，平均仇恨 <= 60%。",
          "知识点：这就是“参与度最优化”的两难。只追停留会把系统推向极化；只追安全会牺牲商业。你要做的是可持续平衡。"
        ].join("\n\n"), [
          { label: "开始值班", onClick: () => {} }
        ]);
      }

      function openModal(title, body, actions) {
        modalRoot.classList.remove("hidden");
        modalRoot.classList.add("flex");
        modalRoot.innerHTML = `
          <div class="w-full max-w-2xl rounded-2xl border border-neon-cyan/30 bg-monitor-dark/95 p-5 shadow-[0_18px_50px_rgba(0,0,0,0.6)]">
            <h3 class="text-xl font-black text-white mb-3">${title}</h3>
            <div class="text-sm text-slate-200 leading-7 whitespace-pre-wrap">${body}</div>
            <div class="mt-4 flex flex-wrap gap-2" id="modal-actions"></div>
          </div>
        `;
        const host = document.getElementById("modal-actions");
        (actions || []).forEach((action, idx) => {
          const btn = document.createElement("button");
          btn.type = "button";
          btn.className = idx === 0
            ? "px-3 py-2 rounded-lg border border-neon-cyan/50 bg-neon-cyan/15 text-neon-cyan text-sm font-bold hover:bg-neon-cyan/25"
            : "px-3 py-2 rounded-lg border border-white/25 bg-white/5 text-slate-100 text-sm font-bold hover:bg-white/10";
          btn.textContent = action.label;
          btn.addEventListener("click", () => {
            action.onClick && action.onClick();
            modalRoot.classList.add("hidden");
            modalRoot.classList.remove("flex");
            modalRoot.innerHTML = "";
          });
          host.appendChild(btn);
        });
      }

      function showResultModal(success, title, detail) {
        openModal(title, detail, [
          { label: success ? "再来一局" : "从头重开", onClick: () => restartGame() },
          { label: "关闭", onClick: () => {} }
        ]);
      }

      function renderUserCard(user) {
        const selected = state.selectedUserId === user.id;
        const feed = user.feed.slice(-4).reverse();
        const interestColor = user.interest >= 60 ? "text-neon-cyan" : (user.interest >= 35 ? "text-amber-300" : "text-neon-red");
        const hateColor = user.hate >= 70 ? "text-neon-red text-glow-red" : (user.hate >= 45 ? "text-amber-300" : "text-neon-red");

        return `
          <article data-user-id="${user.id}" class="monitor-frame rounded-xl p-3 md:p-4 border-t-2 ${selected ? "border-t-neon-cyan/80 ring-1 ring-neon-cyan/60" : "border-t-neon-cyan/30"} cursor-pointer hover:ring-1 hover:ring-neon-cyan/45 transition-all">
            <div class="flex gap-3 items-start mb-3 border-b border-white/8 pb-3">
              <div class="relative shrink-0">
                <img src="${MEDIA_BASE + user.avatar}" alt="${user.label}" class="w-12 h-12 rounded-full object-cover border border-neon-cyan/30" />
                <div class="absolute -bottom-1 -right-1 w-3 h-3 rounded-full ${user.interest > 25 ? "bg-neon-green" : "bg-neon-red"} shadow-[0_0_6px_currentColor]"></div>
              </div>
              <div class="min-w-0 flex-1">
                <div class="flex items-center justify-between gap-2">
                  <h3 class="font-bold text-white text-sm truncate">${user.label}</h3>
                  <span class="text-[10px] px-1.5 py-0.5 rounded border ${selected ? "border-neon-cyan/50 text-neon-cyan" : "border-slate-500/50 text-slate-300"}">${selected ? "已选中" : "在线"}</span>
                </div>
                <p class="text-[11px] text-slate-400 mt-0.5">${user.name}</p>
                <div class="flex flex-wrap gap-1 mt-1 text-[10px] text-slate-300">
                  ${user.tags.map((tag) => `<span class="bg-white/8 px-1.5 py-0.5 rounded">#${tag}</span>`).join("")}
                </div>
              </div>
            </div>

            <div class="space-y-2 text-xs font-mono">
              <div>
                <div class="flex justify-between mb-0.5"><span class="text-neon-cyan">兴趣值 Interest</span><span class="${interestColor}">${user.interest}%</span></div>
                <div class="h-1.5 bg-slate-800 rounded-full overflow-hidden"><div class="h-full bg-neon-cyan transition-all duration-300" style="width:${user.interest}%;"></div></div>
              </div>
              <div>
                <div class="flex justify-between mb-0.5"><span class="text-neon-red">仇恨值 Hate</span><span class="${hateColor}">${user.hate}%</span></div>
                <div class="h-1.5 bg-slate-800 rounded-full overflow-hidden"><div class="h-full bg-neon-red transition-all duration-300" style="width:${user.hate}%;"></div></div>
              </div>
            </div>

            <div class="mt-3 rounded-lg border border-white/10 bg-white/5 p-2 text-[11px] leading-5 space-y-1">
              <p class="text-emerald-200"><span class="material-symbols-outlined align-[-2px] text-[13px] mr-1">bolt</span>${user.lastActivity || randomFrom(user.activity)}</p>
              <p class="text-cyan-100"><span class="material-symbols-outlined align-[-2px] text-[13px] mr-1">chat</span>${user.lastSaying || randomFrom(user.saying)}</p>
              <p class="text-amber-100"><span class="material-symbols-outlined align-[-2px] text-[13px] mr-1">shopping_cart</span>${user.lastSpending || randomFrom(user.spending)}</p>
            </div>

            <div class="mt-3 text-[11px] text-slate-300">瀑布流尾部（最新在上）</div>
            <div class="mt-2 space-y-2 max-h-40 overflow-y-auto pr-1 scrollbar-hide">
              ${feed.length ? feed.map((entry) => `
                <div class="rounded border ${entry.type === "hot" ? "border-neon-red/45" : entry.type === "ad" ? "border-amber-300/40" : "border-neon-cyan/35"} bg-black/30 p-2 text-[11px]">
                  <div class="flex justify-between mb-1 text-[10px] text-slate-400"><span>R${entry.round}</span><span>${entry.type === "ad" ? "广告" : entry.type === "hot" ? "争议" : "内容"}</span></div>
                  <p class="text-slate-100">${entry.title}</p>
                  <p class="text-[10px] mt-1 ${entry.hateDelta > 0 ? "text-neon-red" : "text-slate-300"}">兴趣 ${entry.interestDelta >= 0 ? "+" : ""}${entry.interestDelta} / 仇恨 ${entry.hateDelta >= 0 ? "+" : ""}${entry.hateDelta}${entry.revenueGain ? ` / 营收 +$${entry.revenueGain}` : ""}</p>
                </div>
              `).join("") : ''<div class="rounded border border-dashed border-white/20 bg-black/20 p-3 text-[11px] text-slate-500 text-center">等待算法推送...</div>''}
            </div>
          </article>
        `;
      }

      function renderPoolCard(item) {
        const selected = state.selectedPoolId === item.turnId;
        const badge = item.type === "ad"
          ? `<span class="text-[10px] px-1.5 py-0.5 rounded border border-amber-300/40 bg-amber-300/15 text-amber-200">AD · CPM $${item.cpm.toFixed(1)}</span>`
          : item.type === "hot"
            ? ''<span class="text-[10px] px-1.5 py-0.5 rounded border border-neon-red/50 bg-neon-red/15 text-neon-red">争议内容</span>''
            : ''<span class="text-[10px] px-1.5 py-0.5 rounded border border-neon-cyan/40 bg-neon-cyan/10 text-neon-cyan">普通内容</span>'';
        return `
          <article data-pool-id="${item.turnId}" class="rounded-lg border ${selected ? "border-neon-cyan/75 ring-1 ring-neon-cyan/60" : item.type === "hot" ? "border-neon-red/45" : item.type === "ad" ? "border-amber-300/40" : "border-white/20"} bg-monitor-dark/85 p-2.5 cursor-pointer hover:border-neon-cyan/65 transition-all">
            <div class="h-24 rounded-md overflow-hidden border border-white/10 bg-slate-900/60">
              <img src="${MEDIA_BASE + item.image}" alt="${item.title}" class="w-full h-full object-cover"/>
            </div>
            <div class="mt-2 flex items-center justify-between gap-2">${badge}<span class="text-[10px] text-slate-400">${item.tags.map((tag) => `#${tag}`).slice(0, 2).join(" ")}</span></div>
            <h4 class="mt-1 text-sm font-bold text-white leading-5">${item.title}</h4>
            <p class="mt-1 text-[11px] text-slate-300 line-clamp-2">${item.summary}</p>
          </article>
        `;
      }

      function render() {
        const activeUsers = getActiveUsers();
        const avgInterest = Math.round(average(activeUsers.map((user) => user.interest)));
        const avgHate = Math.round(average(activeUsers.map((user) => user.hate)));

        if (!state.selectedUserId || !state.activeSlots.includes(state.selectedUserId)) {
          state.selectedUserId = state.activeSlots[0];
        }

        userBoard.innerHTML = activeUsers.map(renderUserCard).join("");
        poolGrid.innerHTML = state.pool.length
          ? state.pool.map(renderPoolCard).join("")
          : ''<div class="col-span-full rounded-lg border border-dashed border-white/20 p-4 text-sm text-slate-400 text-center">内容池已空，点击“换一批候选”。</div>'';

        metricRevenue.textContent = `$${state.revenue}`;
        metricAds.textContent = `${state.adViews}`;
        metricInterest.textContent = `${avgInterest}%`;
        metricHate.textContent = `${avgHate}%`;
        metricRound.textContent = `${Math.min(state.round, state.maxRounds)} / ${state.maxRounds}`;

        const progress = Math.round((Math.min(state.round - 1, state.maxRounds) / state.maxRounds) * 100);
        roundProgress.style.width = `${progress}%`;
        slotHint.textContent = `当前在线：${activeUsers.map((user) => user.label.replace("用户_ID: ", "#")).join(" · ")}`;

        goalHint.textContent = `目标：28 回合后营收 >= $${TARGET_REVENUE}；当前剩余回合 ${Math.max(0, state.maxRounds - state.round + 1)}。平均兴趣 ${avgInterest}% / 平均仇恨 ${avgHate}%。`;
        selectionHint.textContent = state.gameOver
          ? "本局已结束，可重新开局"
          : `已选目标：${(getUserById(state.selectedUserId) || {}).label || "未选择"} · ${state.actionResolved ? "可结束本回合" : "请从下方内容池选择一条内容"}`;

        eventLog.innerHTML = state.logs.length
          ? state.logs.map((line) => `<li class="rounded border border-white/10 bg-black/25 px-2 py-1">${line}</li>`).join("")
          : ''<li class="text-slate-500">日志为空，开始第一回合分发。</li>'';

        document.querySelectorAll("[data-user-id]").forEach((node) => {
          node.addEventListener("click", () => {
            if (state.gameOver) return;
            const id = node.getAttribute("data-user-id");
            if (!id) return;
            state.selectedUserId = id;
            render();
          });
        });

        document.querySelectorAll("[data-pool-id]").forEach((node) => {
          node.addEventListener("click", () => {
            if (state.gameOver || state.actionResolved) return;
            const poolId = node.getAttribute("data-pool-id");
            if (!poolId || !state.selectedUserId) return;
            state.selectedPoolId = poolId;
            dispatchContentToUser(poolId, state.selectedUserId);
          });
        });
      }

      function restartGame() {
        state.round = 1;
        state.revenue = 0;
        state.adViews = 0;
        state.selectedPoolId = "";
        state.actionResolved = false;
        state.gameOver = false;
        state.users = USERS.map((item) => ({ ...item, feed: [], lastActivity: "", lastSaying: "", lastSpending: "" }));
        state.activeSlots = ["u9942", "u3301", "u5520"];
        state.benchQueue = ["u7824", "u1170", "u8841", "u2059", "u6412", "u7390", "u9183"];
        state.selectedUserId = state.activeSlots[0];
        state.logs = [];
        buildPool();
        endTurnBtn.disabled = true;
        actionResult.textContent = "新局已开始：请选择一个用户，再从内容池派发一条内容。";
        pushLog("新局开始：算法值班上线。", "ok");
        render();
      }

      endTurnBtn.addEventListener("click", endTurn);
      refreshPoolBtn.addEventListener("click", () => {
        if (state.gameOver || state.actionResolved) return;
        buildPool();
        pushLog("你刷新了候选内容池。注意：频繁刷新会错过稳定机会。", "normal");
        render();
      });
      openGuideBtn.addEventListener("click", openGuide);
      restartTopBtn.addEventListener("click", restartGame);
      restartBottomBtn.addEventListener("click", restartGame);

      restartGame();
      openGuide();
    })();
  </script>
</body>
</html>
